    //AsyncTask searchTask
    public static void webServiceAsyncTask(final WebServiceID webServiceID, final DoInBackground background, final OnPostExecute postExecute, final String... parameters) {

        //if asyncTask = null, then execute
        if (webServiceID.getAsyncTask() == null || webServiceID.getDisableNullRestriction()) {
            AsyncTask asyncTask = new AsyncTask<Object, Object, Object>() {
                Exception e;

                @Override
                protected Object doInBackground(Object... params) {
                    try {
                        if (background != null) {  //specify do in the backgruond
                            return background.doInBackground();
                        } else if (webServiceID.getBackground() != null) {    //not specifying do in the background
                            return webServiceID.getBackground().doInBackground();
                        } else {
                            return WebService.getInstance().callingWebservice(webServiceID, parameters);
                        }
                    } catch (Exception e) {
                        this.e = e;
                    }
                    return null;
                }

                @Override
                protected void onPostExecute(Object result) {
                    webServiceID.setAsyncTask(null);
                    if (result == null || ((result instanceof Integer) && ((Integer) result).intValue() == -1)) {
                        return;
                    }

                    if (postExecute != null) {
                        postExecute.onPostExecute(result);
                    } else if (webServiceID.getPostExecute() != null) {
                        webServiceID.getPostExecute().onPostExecute(result);
                    }

                }
            }.execute();

            //set AsyncTask
            webServiceID.setAsyncTask(asyncTask);
        }
    }
