    public class WebServiceException extends Exception {
        WebServiceException(String message) {
            super(message);
        }
    }

    public Object RxCallingWebservice(final WebServiceID webServiceID, final String... parameters) throws WebServiceException, InterruptedException {

        Object result = callingWebservice(webServiceID, parameters);

        if (result == null || ((result instanceof Integer) && ((Integer) result).intValue() == -1)) {
            throw new WebServiceException("Webservice Call: " + webServiceID.toString() + " Failed");
        }

        return result;
    }

